-- model_settings.py no longer maps the route names saved before the Router served native model IDs; rewrite them once.
WITH legacy(old, new) AS (VALUES ('models/sol-6-1', 'gpt-6.1-sol'), ('models/claude-opus-5-5', 'claude-opus-5-5'), ('models/claude-haiku-5-5', 'claude-haiku-5-5'), ('models/gemini-email', 'gemini-3.5-flash-lite'), ('models/gemini-report', 'gemini-3.8-flash'), ('models/gemini-3-5-flash-lite', 'gemini-3.5-flash-lite'), ('models/gemini-3-8-flash', 'gemini-3.8-flash'), ('models/gemini-3-7-flash', 'gemini-3.8-flash'), ('gemini-3.7-flash', 'gemini-3.8-flash'))
UPDATE model_settings SET email_model = coalesce((SELECT new FROM legacy WHERE old = email_model), email_model), report_model = coalesce((SELECT new FROM legacy WHERE old = report_model), report_model);
